export function createCatalog(rows) {
 const cache = new Map();
 return { search(query, rules) {
  if (cache.has(query)) return cache.get(query);
  const result = rows.filter(r => r.name.includes(query) && r.stock >= rules.minStock).map(r => ({id:r.id,name:r.name,stock:r.stock}));
  cache.set(query,result); return result;
 }};
}

